ROOT = Path(__file__).resolve().parent
STEM = 'more-party-games'
games = []

def example(title, prompt, answer, preparation='Только текст.', mode='Вопрос на поле', facts=()):
    return dict(title=title, prompt=prompt, answer=answer, preparation=preparation,
                mode=mode, fact_sources=list(facts), origin='Авторская адаптация, не задание из оригинальной игры')

def game(id, title, language, family, url, verified, borrow, fit, limitation, examples, extra=(), recommended=False):
    games.append(dict(id=id, title=title, language=language, family=family, url=url,
        verified=verified, borrow=borrow, fit=fit, limitation=limitation,
        examples=examples, extra=list(extra), recommended=recommended))

def ref(title, url):
    return dict(title=title, url=url)

CRAFT = ref('Mojang: How to craft', 'https://www.minecraft.net/en-us/article/how-craft')
