old = json.loads((ROOT / 'internet-party-games.json').read_text())
assert not ({g['url'].rstrip('/') for g in games} & {s['url'].rstrip('/') for s in old['sources']})
all_examples = [e for g in games for e in g['examples']]
source_urls = {g['url'] for g in games}
for g in games:
    for r in g['extra']:
        source_urls.add(r['url'])
    for e in g['examples']:
        for r in e['fact_sources']:
            source_urls.add(r['url'])
data = dict(format='dibs/further-game-research/1', title='Ещё 20 игр: новые механики для нашего вечера',
    checked_at='2026-11-03', game_count=len(games), example_count=len(all_examples),
    source_count=len(source_urls), methodology=methodology, guide=guide, games=games)
(ROOT / f'{STEM}.json').write_text(json.dumps(data, ensure_ascii=False, indent=2) + '\n')

md = ['# ' + data['title'], '', 'Проверено: 03.11.2026 · 20 дополнительных игр · 40 авторских примеров · 8 RU / 11 EN / 1 FR.', '',
      '**Спойлеры. Каталог для подготовки, не пакет для импорта.**', '', '## Как выбирать', '']
for r in guide:
    md += ['- **' + r['title'] + '.** ' + r['text']]
md += ['', '## Методика и ограничения', ''] + ['- ' + m for m in methodology]
for g in games:
    md += ['', f"## {g['id']}. {g['title']}", '', f"{g['language']} · {g['family']} · {g['fit']}", '',
        f"[Источник механики]({g['url']})", '', '**Проверено:** ' + g['verified'], '',
        '**Что взять:** ' + g['borrow'], '', '**Границы адаптации:** ' + g['limitation'], '']
    for r in g['extra']:
        md += [f"- [{r['title']}]({r['url']})"]
    for e in g['examples']:
        md += ['', '### ' + e['title'], '', '**Авторский пример · ' + e['mode'] + ':** ' + e['prompt'], '',
            '**Ответ / критерий:** ' + e['answer'], '', '**Подготовка:** ' + e['preparation'], '']
        for r in e['fact_sources']:
            md += [f"- Проверка факта: [{r['title']}]({r['url']})"]
(ROOT / f'{STEM}.md').write_text('\n'.join(md) + '\n')

# Reuse only the established reports' style constant, without running their builder.
tree = ast.parse((ROOT / 'build-internet-party-report.py').read_text())
style = next(ast.literal_eval(n.value) for n in tree.body if isinstance(n, ast.Assign)
             and any(isinstance(t, ast.Name) and t.id == 'STYLE' for t in n.targets))
style += '''
button[aria-pressed=true]{background:#a84326;color:white;border-color:#a84326}
.game-list{display:grid;gap:22px}.game-card{background:#fffdf7;border:1px solid #d6d8cb;border-radius:8px;padding:25px;scroll-margin-top:150px}.game-card h2{margin:8px 0 12px}.game-card .grid{margin-top:18px}.sample-card{background:#f2efe6;border-radius:6px;padding:18px;min-width:0}.sample-card h3{font-size:19px}.sample-card p{overflow-wrap:anywhere}.lead{max-width:1000px}.shortcuts{display:flex;gap:10px;flex-wrap:wrap}.badge{color:#85502d;font-weight:650}.jump-list{display:flex;gap:6px;flex-wrap:wrap}.source-table{width:100%;border-collapse:collapse}.source-table td,.source-table th{text-align:left;vertical-align:top;padding:14px 10px;border-bottom:1px solid #d6d8cb}.source-table th{font-size:13px}.source-table a{overflow-wrap:anywhere}.source-table td:first-child{white-space:nowrap}.source-table caption{text-align:left;margin:12px 0}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}@media(max-width:700px){.game-card{padding:17px}.source-table th:nth-child(2),.source-table td:nth-child(2){display:none}.game-card .grid{grid-template-columns:1fr}}:focus-visible{outline:3px solid #ad492a;outline-offset:3px}
'''
template = '''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ещё 20 игр — исследование для Dibs</title><style>__STYLE__</style></head><body>
<nav class="back" aria-label="Другие отчёты"><a href="internet-party-games.html">Первый обзор игр</a> · <a href="prague-genz-categories.html">Категории для нашей компании</a> · <a href="svoyak-categories.html">«Свояк»</a></nav>
<header><h1>Ещё 20 игр для нашего вечера</h1><p class="meta">20 дополнительных игр · 40 авторских примеров · 8 RU / 11 EN / 1 FR · 03.11.2026</p>
<p class="lead">Новые механики из русскоязычных настолок и международных party games: секретные коды, абсурдные шкалы, коллективное мышление и ответы из чужих слов. Примеры под нашу компанию: Прага, мемы, боулдеринг, деньги и Minecraft.</p>
<p class="notice"><strong>Подготовка со спойлерами.</strong> Все примеры придуманы для этого отчёта. Источники подтверждают правила оригинальных игр. Это не просмотр всех партий и не копия платных колод. Часть примеров можно перенести в поле; для других нужна бумага и ручное проведение.</p>
<p><a href="more-party-games.md">Markdown</a> · <a href="more-party-games.json">JSON каталога</a></p>
<div class="shortcuts"><button id="quick-board">Для обычного поля</button><button id="quick-minecraft">Примеры с Minecraft</button><button id="quick-best">Короткий список</button></div>
<details class="lead"><summary>Как исследовали и что проверено</summary><div id="method"></div></details></header>
<div class="tabs" aria-label="Разделы отчёта"><button id="tab-games" aria-pressed="true">Игры и примеры — 20</button><button id="tab-guide" aria-pressed="false">Что взять для вечера</button><button id="tab-sources" aria-pressed="false">Источники</button></div>
<div id="tools" class="tools"><label class="sr-only" for="search">Поиск</label><input id="search" type="search" placeholder="Minecraft, код, Прага, мемы…"><select id="lang" aria-label="Язык источника"><option value="">Все языки</option><option>RU</option><option>EN</option><option>FR</option></select><select id="family" aria-label="Механика"><option value="">Все механики</option></select><select id="fit" aria-label="Совместимость с Dibs"><option value="">Любая подготовка</option></select><select id="pick" aria-label="Подборка"><option value="">Все игры</option><option value="best">Короткий список</option></select><button id="reset">Сбросить</button></div>
<div class="counts"><span id="shown" class="muted" aria-live="polite"></span><button id="answers">Открыть все ответы</button></div>
<main><section id="games-panel" aria-label="Игры и примеры"><div id="games" class="game-list"></div><p id="empty" hidden>Ничего не найдено. Попробуйте убрать фильтры.</p></section>
<section id="guide-panel" class="guide" aria-label="Что взять для вечера" hidden><h2>С чего я бы начал</h2><div id="guide"></div><h2>Самое простое тестовое поле</h2><p>Шесть категорий по два примера: «Инвентарь и чат на букву», «Соединяем пары», «Декодер», «Четыре намёка», «Подсказки без повторов», «Три штуки». Это черновик для выбора. Перед игрой заменить пересекающиеся разгадки и проверить вопросы на одном человеке.</p><p class="notice">Не пытайтесь разместить все 20 механик в одном вечере. Для первой игры достаточно обычного поля и одной отдельной творческой вставки. Новые режимы в приложение для этих адаптаций не добавлялись.</p></section>
<section id="sources-panel" aria-label="Источники" hidden><h2>Что подтверждают источники</h2><p>Открытые страницы издателей и разработчиков подтверждают механики. Ссылки Mojang проверяют отдельные игровые факты. Формулировки, вымышленные сценки и домашние правила — наши. Дата проверки: 03.11.2026.</p><table class="source-table"><caption id="source-count"></caption><thead><tr><th scope="col">Игра</th><th scope="col">Язык</th><th scope="col">Проверено и ссылки</th></tr></thead><tbody id="sources"></tbody></table></section></main>
<footer>Локальные материалы в Git-игнорируемой папке research. Каталог JSON не импортируется как игра. Действующие игры и предыдущие отчёты не менялись.</footer>
<script id="catalog-data" type="application/json">__DATA__</script><script>
const d=JSON.parse(document.getElementById('catalog-data').textContent),$=id=>document.getElementById(id);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=s=>String(s).toLocaleLowerCase('ru').replaceAll('ё','е'),link=r=>`<a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.title)} ↗</a>`;
const exampleWord=n=>n%100>=11&&n%100<=14?'примеров':n%10===1?'пример':n%10>=2&&n%10<=4?'примера':'примеров';
let mode='games',openAnswers=false;
const filterIds=['search','lang','family','fit','pick'];
for(const field of ['family','fit'])$(field).innerHTML+=[...new Set(d.games.map(g=>g[field]))].sort().map(v=>`<option>${esc(v)}</option>`).join('');
$('method').innerHTML=d.methodology.map(m=>`<p>${esc(m)}</p>`).join('');
$('guide').innerHTML=d.guide.map(r=>`<article><h3>${esc(r.title)}</h3><p>${esc(r.text)}</p><p class="jump-list">${r.ids.map(id=>{const g=d.games.find(x=>x.id===id);return `<a href="#game-${id}" data-game="${id}">${esc(g.title)}</a>`;}).join(' · ')}</p></article>`).join('');
function render(){const q=norm($('search').value.trim());const rows=d.games.filter(g=>(!q||norm(JSON.stringify(g)).includes(q))&&(!$('lang').value||g.language===$('lang').value)&&(!$('family').value||g.family===$('family').value)&&(!$('fit').value||g.fit===$('fit').value)&&(!$('pick').value||g.recommended));
$('games').innerHTML=rows.map(g=>`<article class="game-card" id="game-${g.id}"><div class="muted">${g.id} · ${esc(g.language)}${g.recommended?' · <span class="badge">В коротком списке</span>':''}</div><h2>${esc(g.title)}</h2><span class="pill">${esc(g.family)}</span><span class="pill">${esc(g.fit)}</span><p><strong>Оригинал.</strong> ${esc(g.verified)}</p><p><strong>Что взять.</strong> ${esc(g.borrow)}</p><details><summary>Границы адаптации</summary><p>${esc(g.limitation)}</p></details><p class="source-links">${link({title:'Источник механики',url:g.url})}${g.extra.map(link).join(' · ')}</p><div class="grid">${g.examples.map(e=>`<section class="sample-card"><span class="pill">${esc(e.mode)}</span><h3>${esc(e.title)}</h3><div class="label">Авторский пример</div><p>${esc(e.prompt)}</p><details class="answer" ${openAnswers?'open':''}><summary>Ответ / критерий</summary><p>${esc(e.answer)}</p></details><p><strong>Подготовка.</strong> ${esc(e.preparation)}</p>${e.fact_sources.length?`<p class="source-links">Проверка факта: ${e.fact_sources.map(link).join(' · ')}</p>`:''}</section>`).join('')}</div></article>`).join('');
$('shown').textContent=mode==='games'?`Показано ${rows.length} из ${d.game_count} игр · ${rows.length*2} ${exampleWord(rows.length*2)}`:mode==='sources'?`${d.game_count} игр · ${d.source_count} уникальных ссылок`:'Рекомендации для вашей компании';
$('empty').hidden=rows.length>0;$('tools').hidden=mode!=='games';$('answers').hidden=mode!=='games';}
function tab(m){mode=m;for(const x of ['games','guide','sources']){$(x+'-panel').hidden=x!==m;$('tab-'+x).setAttribute('aria-pressed',String(x===m));}render();}
for(const m of ['games','guide','sources'])$('tab-'+m).onclick=()=>tab(m);
for(const id of filterIds)$(id).addEventListener(id==='search'?'input':'change',render);
function clear(){for(const id of filterIds)$(id).value='';}
$('reset').onclick=()=>{clear();render();};
$('answers').onclick=()=>{openAnswers=!openAnswers;document.querySelectorAll('details.answer').forEach(e=>e.open=openAnswers);$('answers').textContent=openAnswers?'Скрыть все ответы':'Открыть все ответы';};
$('quick-board').onclick=()=>{clear();$('fit').value='Отлично для поля';tab('games');};
$('quick-minecraft').onclick=()=>{clear();$('search').value='Minecraft';tab('games');};
$('quick-best').onclick=()=>{clear();$('pick').value='best';tab('games');};
$('source-count').textContent=`${d.source_count} уникальных ссылок по ${d.game_count} играм`;
$('sources').innerHTML=d.games.map(g=>`<tr><th scope="row"><a href="#game-${g.id}" data-game="${g.id}">${esc(g.title)}</a></th><td>${esc(g.language)}</td><td><p>${esc(g.verified)}</p><p>${[link({title:'Основной источник',url:g.url}),...g.extra.map(link)].join(' · ')}</p>${g.examples.some(e=>e.fact_sources.length)?'<p>Факты примеров: '+[...new Map(g.examples.flatMap(e=>e.fact_sources).map(r=>[r.url,r])).values()].map(link).join(' · ')+'</p>':''}</td></tr>`).join('');
function jump(id){if(!d.games.some(g=>g.id===id))return;clear();tab('games');$('game-'+id).scrollIntoView({behavior:'smooth'});history.replaceState(null,'','#game-'+id);}
document.addEventListener('click',e=>{const a=e.target.closest('a[data-game]');if(a){e.preventDefault();jump(a.dataset.game);}});
render();if(location.hash.startsWith('#game-'))jump(location.hash.slice(6));
</script></body></html>'''
payload = json.dumps(data, ensure_ascii=False).replace('<', '\\u003c').replace('&', '\\u0026')
(ROOT / f'{STEM}.html').write_text(template.replace('__STYLE__', style).replace('__DATA__', payload))
print(json.dumps(dict(games=len(games), examples=len(all_examples), sources=len(source_urls),
    languages={k:sum(g['language']==k for g in games) for k in ['RU','EN','FR']})))
